def linear_search(items, target):
    for index, value in enumerate(items):
        if value == target:
            return index
    return -1

def binary_search(items, target):
    left, right = 0, len(items) - 1

    while left <= right:
        middle = (left + right) // 2
        if items[middle] == target:
            return middle
        if items[middle] < target:
            left = middle + 1
        else:
            right = middle - 1

    return -1

def lower_bound(items, target):
    left, right = 0, len(items)
    while left < right:
        middle = (left + right) // 2
        if items[middle] >= target:
            right = middle
        else:
            left = middle + 1
    return left

def upper_bound(items, target):
    left, right = 0, len(items)
    while left < right:
        middle = (left + right) // 2
        if items[middle] > target:
            right = middle
        else:
            left = middle + 1
    return left

def minimum_speed(tasks, hours_limit):
    def can_finish(speed):
        needed = sum((task + speed - 1) // speed for task in tasks)
        return needed <= hours_limit

    left, right = 1, max(tasks)
    while left < right:
        middle = (left + right) // 2
        if can_finish(middle):
            right = middle
        else:
            left = middle + 1
    return left

def dfs(graph, start):
    order = []
    stack = [start]
    visited = {start}

    while stack:
        node = stack.pop()
        order.append(node)
        for neighbor in reversed(graph.get(node, [])):
            if neighbor not in visited:
                visited.add(neighbor)
                stack.append(neighbor)

    return order

from collections import deque

def bfs_distances(graph, start):
    queue = deque([start])
    distance = {start: 0}

    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor not in distance:
                distance[neighbor] = distance[node] + 1
                queue.append(neighbor)

    return distance
